import pandas as pd
import numpy as np
from sklearn.pipeline import Pipeline, FeatureUnion
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.linear_model import LogisticRegression, Ridge
from sklearn.metrics import accuracy_score
from scipy.stats import pearsonr, spearmanr

# cyclase
train = pd.read_csv('/task/problem/data/cyclase_peptide_pair/train.csv')
val = pd.read_csv('/task/problem/data/cyclase_peptide_pair/val.csv')

def joiner(df):
    return (df['Cyclase sequence'].str.replace('', ' ', regex=False) + ' [SEP] ' + df['Core'].str.replace('', ' ', regex=False)).tolist()

def cyclase_eval(analyzer, ngram_range, C=4.0):
    pipe = Pipeline([
        ('tfidf', TfidfVectorizer(analyzer=analyzer, ngram_range=ngram_range, min_df=2, sublinear_tf=True)),
        ('clf', LogisticRegression(max_iter=2000, C=C, n_jobs=1))
    ])
    pipe.fit(joiner(train), train['label'])
    pred = pipe.predict(joiner(val))
    return accuracy_score(val['label'], pred)

for analyzer, ngr in [('char',(2,4)), ('char_wb',(3,5)), ('word',(1,3))]:
    try:
        acc = cyclase_eval(analyzer, ngr)
        print('cyclase', analyzer, ngr, acc)
    except Exception as e:
        print('cyclase failed', analyzer, ngr, e)

# ubonodin
utr = pd.read_csv('/task/problem/data/ubonodin_rnap_inhibition/train.csv')
uval = pd.read_csv('/task/problem/data/ubonodin_rnap_inhibition/val.csv')

def spaced(seq_series):
    return seq_series.apply(lambda s: ' '.join(list(s))).tolist()

def ubo_eval(analyzer, ngram_range, alpha=1.0):
    pipe = Pipeline([
        ('tfidf', TfidfVectorizer(analyzer=analyzer, ngram_range=ngram_range, min_df=1, sublinear_tf=True)),
        ('reg', Ridge(alpha=alpha))
    ])
    pipe.fit(spaced(utr['Full_Sequence']), utr['Score'])
    pred = pipe.predict(spaced(uval['Full_Sequence']))
    p = pearsonr(uval['Score'], pred).statistic
    s = spearmanr(uval['Score'], pred).statistic
    mae = np.mean(np.abs(uval['Score'] - pred))
    return p, s, mae

for analyzer, ngr, alpha in [('char',(2,4),1.0), ('char_wb',(2,5),1.0), ('word',(1,3),1.0)]:
    try:
        print('ubo', analyzer, ngr, ubo_eval(analyzer, ngr, alpha))
    except Exception as e:
        print('ubo failed', analyzer, ngr, e)
