import itertools
import numpy as np
import pandas as pd
from sklearn.feature_extraction import DictVectorizer
from sklearn.linear_model import Ridge
from scipy.stats import pearsonr
tr = pd.read_csv('/task/problem/data/ubonodin_rnap_inhibition/train.csv')
va = pd.read_csv('/task/problem/data/ubonodin_rnap_inhibition/val.csv')
L = len(tr['Full_Sequence'][0])
wt = ''.join(tr['Full_Sequence'].str[i].mode().iloc[0] for i in range(L))

def feat(seq, pairwise=True, triple=False):
    d={}
    muts=[]
    for i,ch in enumerate(seq,1):
        d[f'p{i}={ch}']=1
        if ch!=wt[i-1]:
            tok=f'm{i}={ch}'
            d[tok]=1
            muts.append(tok)
    d['num_mut']=len(muts)
    if pairwise:
        for a,b in itertools.combinations(muts,2):
            d[f'{a}|{b}']=1
    if triple:
        for a,b,c in itertools.combinations(muts,3):
            d[f'{a}|{b}|{c}']=1
    return d

def train_pred(alpha, pairwise, triple, dedup):
    td = tr.groupby('Full_Sequence', as_index=False).agg({'Score':'mean'}) if dedup else tr
    vec=DictVectorizer()
    Xtr=vec.fit_transform([feat(s, pairwise=pairwise, triple=triple) for s in td['Full_Sequence']])
    Xva=vec.transform([feat(s, pairwise=pairwise, triple=triple) for s in va['Full_Sequence']])
    model=Ridge(alpha=alpha).fit(Xtr, td['Score'])
    return model.predict(Xva)
models={
    'pt5':train_pred(5,True,True,False),
    'pt10':train_pred(10,True,True,False),
    'dpt5':train_pred(5,True,True,True),
    'dpt10':train_pred(10,True,True,True),
    'p5':train_pred(5,True,False,False),
    'p10':train_pred(10,True,False,False),
}
for name,p in models.items():
    print(name, pearsonr(va['Score'], p).statistic)
from itertools import combinations
best=(0,None)
for r in range(2,5):
    for combo in combinations(models,r):
        pred=np.mean([models[c] for c in combo],axis=0)
        val=pearsonr(va['Score'], pred).statistic
        if val>best[0]: best=(val,combo)
print('best',best)
